import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%82%A2%E3%83%86%E3%83%B3%E3%82%B7%E3%83%A7%E3%83%B3.html","title":"アテンション","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.87,"words":561},"filePathRelative":"アテンション.md"}`),a={name:`アテンション.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="アテンション" tabindex="-1"><a class="header-anchor" href="#アテンション"><span>アテンション</span></a></h1><p><a href="./機械翻訳.html">機械翻訳</a></p><p><a href="./論文.html">論文</a>、<a href="https://arxiv.org/abs/1409.0473" target="_blank" rel="noopener noreferrer">arxiv: 1409.0473 Neural Machine Translation by Jointly Learning to Align and Translate</a>,で提唱されたNMTの機構。 <a href="./Transformer.html">Transformer</a>でも（頻繁に）使われる。</p><p>いろいろと変形があるが、基本的にはEncoder-Decoderモデルで、Encoderの最後の状態と現在生成しているDecoderのトークンのどこが対応しているかを、何らかのスコア（内積とか）で定義して、一番近いエンコーダーのアウトプットを特に重く見る、という仕組み。</p><h2 id="定義" tabindex="-1"><a class="header-anchor" href="#定義"><span>定義</span></a></h2><p><img src="/RandomThoughts/assets/0000-DX20gWJh.png" alt="imgs/Attenion/0000.png"></p><p>hの系列と<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>s</mi><mrow><mi>i</mi><mo>−</mo><mn>1</mn></mrow></msub></mrow><annotation encoding="application/x-tex">s_{i-1}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span>のどこが対応しているかを調べて、その結果を入力に使う。 cの式は<a href="./SoftMax.html">SoftMax</a>になっているので一番スコアの高いhが選ばれる。</p><p>scoreは元論文ではalignment modelと言われていて1層のNNが使われていたが、その後単なる内積が使われる事が多くなったと思う。 Encoder-Decoder以外でも広く使われるようになった現在では、単純にscoreと見ておくのが良いと思いそうした。</p><h3 id="パラメータの数" tabindex="-1"><a class="header-anchor" href="#パラメータの数"><span>パラメータの数</span></a></h3><p>scoreにはiが入っていない。つまり全てのhとsに対して同じ関数が使われる。 score自体にWが入っている事はあるが、iごとに別々のWを用意する事はしない。 つまり入力位置ごとに別々のパラメータを使ったりはしない。</p><p>当然hを作る過程ではそうしたパラメータは入りうるし、まさにアテンションを通してそれらのパラメータを学習するのがやりたい事でもあるが、 それらはアテンションというメカニズムの外の話。</p><p><a href="./Transformerブロック.html">Transformerブロック</a>の方にFully connectedなパーセプトロンとの比較がある。（計算量の比較も）</p><h3 id="_3ステップの演算" tabindex="-1"><a class="header-anchor" href="#_3ステップの演算"><span>3ステップの演算</span></a></h3><p>登場時は上記のようにhidden stateとかコンテキストとかでhとかcとかが使われていたが、<a href="./セルフアテンション.html">セルフアテンション</a>などはそういう前提とはかなり違う入力になるので、 単にn個のインプットとクエリのベクトル、と見る方が良い事もある。 上記の演算を<a href="./セルフアテンション.html">セルフアテンション</a>で見直す時にこの表記で3ステップに分けて考えておく方がいいので、以下にその表記をしておく。</p><p>qと<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">{</mo><msub><mi mathvariant="bold-italic">x</mi><mi>n</mi></msub><mo stretchy="false">}</mo></mrow><annotation encoding="application/x-tex">\\{\\bm{x}_n\\}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">}</span></span></span></span>の演算として書くと、上記の式は以下の3ステップの演算と考えられる。</p><ol><li>qと<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">{</mo><msub><mi mathvariant="bold-italic">x</mi><mi>n</mi></msub><mo stretchy="false">}</mo></mrow><annotation encoding="application/x-tex">\\{\\bm{x}_n\\}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">}</span></span></span></span> の内積をとる</li><li>1の<a href="./SoftMax.html">SoftMax</a>をとる</li><li>2の結果と<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">{</mo><msub><mi mathvariant="bold-italic">x</mi><mi>n</mi></msub><mo stretchy="false">}</mo></mrow><annotation encoding="application/x-tex">\\{\\bm{x}_n\\}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">}</span></span></span></span>の内積をとる</li></ol><h2 id="アテンションの直感的な説明" tabindex="-1"><a class="header-anchor" href="#アテンションの直感的な説明"><span>アテンションの直感的な説明</span></a></h2><p>アテンションとは、n個の候補と、一つのベクトルqを入力として、n個の候補から一つを選ぶ仕組みと考えられる。 マルチプレクサみたいなものだが、qと似ているものを出力する、という所が違う。</p><p><img src="/RandomThoughts/assets/0000-C8Kc8gdn.png" alt="imgs/Attention2/0000.png"></p><p>n個の中から1つを選ぶ、というのが重要。なお、softmaxと平均なのでスコアが2位とか3位もちょっとだけ足し合わせたものになる。（ただし結果は一つのベクトルに要約される事には変わりない）</p><p>なお<a href="./セルフアテンション.html">セルフアテンション</a>はこのyの側もn個になるのでややこしいが、概念的にはやはりyが1つにつき１つを選ぶ、を念頭に、それがn個同時に動くと解釈するのが良いだろう。</p><h2 id="encoder-decoderのダイアグラム" tabindex="-1"><a class="header-anchor" href="#encoder-decoderのダイアグラム"><span>Encoder-Decoderのダイアグラム</span></a></h2><p>当初のEncoder-DecoderのRNNでどう使われていたかをメモしておく。</p><p>現在 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>s</mi><mi>i</mi></msub></mrow><annotation encoding="application/x-tex">s_i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>を出そうとしている時に使うアテンション <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>c</mi><mi>i</mi></msub></mrow><annotation encoding="application/x-tex">c_i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> は以下。</p><p><img src="/RandomThoughts/assets/0001-cxrDxN46.png" alt="imgs/Attenion/0001.png"></p><h2 id="q-k-vによる一般化-拡張" tabindex="-1"><a class="header-anchor" href="#q-k-vによる一般化-拡張"><span>Q, K, Vによる一般化（拡張）</span></a></h2><p><a href="./原論文から解き明かす生成AI.html">原論文から解き明かす生成AI</a>の3.3.2に詳しい。</p><p>アテンションはもともと</p><ol><li>qと<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">{</mo><msub><mi mathvariant="bold-italic">x</mi><mi>n</mi></msub><mo stretchy="false">}</mo></mrow><annotation encoding="application/x-tex">\\{\\bm{x}_n\\}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">}</span></span></span></span> の内積をとる</li><li>1のsoftmaxをとる</li><li>2の結果と<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">{</mo><msub><mi mathvariant="bold-italic">x</mi><mi>n</mi></msub><mo stretchy="false">}</mo></mrow><annotation encoding="application/x-tex">\\{\\bm{x}_n\\}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">}</span></span></span></span>の内積をとる</li></ol><p>という演算。この1と3の<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">{</mo><msub><mi mathvariant="bold-italic">x</mi><mi>n</mi></msub><mo stretchy="false">}</mo></mrow><annotation encoding="application/x-tex">\\{\\bm{x}_n\\}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">}</span></span></span></span>をKとVという別のシンボルを当てて違うものを選べるようにし、 さらに1のqをn個集めたQに拡張する。</p><ol><li><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><msup><mi>K</mi><mi>T</mi></msup></mrow><annotation encoding="application/x-tex">QK^T</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0358em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span></span></span></span></span></span></span> を求める</li><li>1をqの要素側（行方向）にsoftmaxする</li><li>2とVを掛ける</li></ol><p>となる。</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>A</mi><mi>t</mi><mi>t</mi><mi>e</mi><mi>n</mi><mi>t</mi><mi>i</mi><mi>o</mi><mi>n</mi><mo stretchy="false">(</mo><mi>Q</mi><mo separator="true">,</mo><mi>K</mi><mo separator="true">,</mo><mi>T</mi><mo stretchy="false">)</mo><mo>=</mo><mi>s</mi><mi>o</mi><mi>f</mi><mi>t</mi><mi>m</mi><mi>a</mi><mi>x</mi><mo stretchy="false">(</mo><mi>Q</mi><msup><mi>K</mi><mi>T</mi></msup><mo stretchy="false">)</mo><mi>V</mi></mrow><annotation encoding="application/x-tex">Attention(Q, K, T) = softmax(QK^T)V </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">A</span><span class="mord mathnormal">tt</span><span class="mord mathnormal">e</span><span class="mord mathnormal">n</span><span class="mord mathnormal">t</span><span class="mord mathnormal">i</span><span class="mord mathnormal">o</span><span class="mord mathnormal">n</span><span class="mopen">(</span><span class="mord mathnormal">Q</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1413em;vertical-align:-0.25em;"></span><span class="mord mathnormal">so</span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mord mathnormal">t</span><span class="mord mathnormal">ma</span><span class="mord mathnormal">x</span><span class="mopen">(</span><span class="mord mathnormal">Q</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8913em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span></span></span></span></span></p><p>従来の<a href="./アテンション.html">アテンション</a>ではKとVは同じだが、この定式化ではクエリと類似を判定する要素とその結果lookupする対象を分けて別々に指定出来る拡張となっている。</p><p><img src="/RandomThoughts/assets/0000-HV3k_x1s.png" alt="imgs/SelfAttention2/0000.png"><img src="/RandomThoughts/assets/0001-Bl_c2yJE.png" alt="imgs/SelfAttention2/0001.png"></p><h3 id="q-k-vアテンションの図解" tabindex="-1"><a class="header-anchor" href="#q-k-vアテンションの図解"><span>Q, K, Vアテンションの図解</span></a></h3><p><img src="/RandomThoughts/assets/0002-CIBdiGq0.png" alt="imgs/SelfAttention2/0002.png"><img src="/RandomThoughts/assets/0003-H62TwtQE.png" alt="imgs/SelfAttention2/0003.png"></p><h3 id="演習-3-4-qとかkを書き下してアテンションの式になるのを確認" tabindex="-1"><a class="header-anchor" href="#演習-3-4-qとかkを書き下してアテンションの式になるのを確認"><span>演習 3.4 QとかKを書き下してアテンションの式になるのを確認</span></a></h3><p>セルフアテンションの前準備として、<a href="./アテンション.html">アテンション</a>をQ, K, Vを使った式に拡張する。それが元と一致しているかを確認しておく。</p><p><a href="./原論文から解き明かす生成AI.html">原論文から解き明かす生成AI</a>の演習3.4。Q, K, Vでの記述が便利なので、この定式化の計算を確かめておく。</p><p><img src="/RandomThoughts/assets/0000-Td2Xwa5b.png" alt="imgs/SelfAttention/0000.png"><img src="/RandomThoughts/assets/0001-DZ7K6NZd.png" alt="imgs/SelfAttention/0001.png"></p><h2 id="ボツ図いろいろ" tabindex="-1"><a class="header-anchor" href="#ボツ図いろいろ"><span>ボツ図いろいろ</span></a></h2><p><a href="./アテンションとセルフアテンション.html">アテンションとセルフアテンション</a>で喋るのに使った性質の一覧だが、ここに載せるほどの何かでは無い。消すのが惜しいので残しておく。</p><p><img src="/RandomThoughts/assets/0002-C35cEIP6.png" alt="imgs/Attention2/0002.png"></p><p>計算を図示してみたが、あんまり分かりやすくならなかった。</p><p><img src="/RandomThoughts/assets/0001-CwSBSrLX.png" alt="imgs/Attention2/0001.png"></p><p>初期に書いた図。もう少しマルチプレクサっぽく描く方が良いと思い最近は違う描き方になったが消すのもなんなのでお蔵入り。</p><p><img src="/RandomThoughts/assets/0002-Cy2Rd21K.png" alt="imgs/Attenion/0002.png"></p>`,48)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};